function AgentMessageContent({ content }) {
  const lines = String(content || '').split('\n');
  const inline = (text) => text.split(/(\*\*[^*]+\*\*)/g).map((part, i) => part.startsWith('**') && part.endsWith('**') ? <strong key={i}>{part.slice(2,-2)}</strong> : part);
  const chunks = []; let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim().startsWith('|')) {
      const tableLines = []; while (i < lines.length && lines[i].trim().startsWith('|')) tableLines.push(lines[i++]);
      const cells = tableLines.map(row => row.split('|').slice(1,-1).map(c=>c.trim()));
      const body = cells.filter(row => !row.every(c => /^:?-{2,}:?$/.test(c)));
      if (body.length) chunks.push(<div className="agent-md-table-wrap" key={`t${i}`}><table className="agent-md-table"><thead><tr>{body[0].map((c,j)=><th key={j}>{inline(c)}</th>)}</tr></thead><tbody>{body.slice(1).map((row,r)=><tr key={r}>{row.map((c,j)=><td key={j}>{inline(c)}</td>)}</tr>)}</tbody></table></div>);
      continue;
    }
    if (/^\s*[-*]\s+/.test(line)) { const items=[]; while(i<lines.length && /^\s*[-*]\s+/.test(lines[i])) items.push(lines[i++].replace(/^\s*[-*]\s+/,'')); chunks.push(<ul key={`u${i}`}>{items.map((it,j)=><li key={j}>{inline(it)}</li>)}</ul>); continue; }
    if (!line.trim()) { i++; continue; }
    const paragraph=[]; while(i<lines.length && lines[i].trim() && !lines[i].trim().startsWith('|') && !/^\s*[-*]\s+/.test(lines[i])) paragraph.push(lines[i++]); chunks.push(<p key={`p${i}`}>{inline(paragraph.join(' '))}</p>);
  }
  return <div className="agent-message-content">{chunks}</div>;
}


